#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=3
umask 077
SCRIPT_DIR="${BASH_SOURCE[0]%/*}"
[[ "$SCRIPT_DIR" != "${BASH_SOURCE[0]}" ]] || SCRIPT_DIR=.
ENV_FILE="${BOTHARNESS_IM_TEST_APPS_ENV:-$(node -p "require('node:path').join(require('node:os').homedir(), '.config', 'botharness', 'im-test-apps.env').replaceAll(String.fromCharCode(92), '/')")}"
node "$SCRIPT_DIR/dev-im-test-apps.mjs" protect "$ENV_FILE"
export TMPDIR="${ENV_FILE%/*}"

while IFS= read -r line || [[ -n "$line" ]]; do
  [[ "$line" != '# BH_DISCORD_'* ]] || line="${line:2}"
  if [[ "$line" =~ ^(BH_DISCORD_QA_SLOT|BH_DISCORD_QA[123]_[A-Z_]+)=(.*)$ ]]; then
    printf -v "IM_TEST_APP_VALUE_${BASH_REMATCH[1]}" '%s' "${BASH_REMATCH[2]}"
  fi
done < "$ENV_FILE"
_existing() {
  local name="IM_TEST_APP_VALUE_$1"
  [[ -n "${!name+set}" ]] || return 1
  printf '%s' "${!name}"
}
_clear() {
  [[ -t 1 ]] || return 0
  printf '\033[2J\033[H'
}
write_values() {
  local entry key
  printf '%s\n' "$@" | node "$SCRIPT_DIR/dev-im-test-apps.mjs" save
  for entry in "$@"; do
    key="${entry%%=*}"
    printf -v "IM_TEST_APP_VALUE_$key" '%s' "${entry#*=}"
    WRITTEN_ENV+=("$key")
  done
  say "✓ 已保存本阶段配置。"
}
valid_id() {
  node -e 'const v=process.argv[1]; process.exit(/^[1-9][0-9]{16,19}$/.test(v) && BigInt(v)<(1n<<64n) ? 0 : 1)' "$1"
}
valid_name() {
  node -e 'const v=process.argv[1]; process.exit(v.trim() && !/[\u0000-\u001f\u007f]/u.test(v) ? 0 : 1)' "$1"
}
if [[ "${BOTHARNESS_IM_TEST_APPS_NO_OPEN:-}" == 1 ]]; then
  open_url() { say "请打开：$1"; }
fi

setup_mode="${1:---token-only}"
setup_slot="${2:-$(_existing BH_DISCORD_QA_SLOT || true)}"
[[ "$setup_mode" == --token-only || "$setup_mode" == --manual ]] || { warn "请选择 --token-only 或 --manual。"; exit 1; }
if [[ "$setup_mode" == --token-only ]]; then
  [[ "$setup_slot" =~ ^QA[123]$ ]] || { warn "请先让代理准备 Discord QA 槽的应用和测试目的地。"; exit 1; }
  prefix="BH_DISCORD_${setup_slot}"
  app_name=$(_existing "${prefix}_NAME" || true)
  app_id=$(_existing "${prefix}_APP_ID" || true)
  guild_name=$(_existing "${prefix}_GUILD_NAME" || true)
  guild_id=$(_existing "${prefix}_GUILD_ID" || true)
  channel_name=$(_existing "${prefix}_CHANNEL_NAME" || true)
  channel_id=$(_existing "${prefix}_CHANNEL_ID" || true)
  if ! valid_name "$app_name" || ! valid_name "$guild_name" || ! valid_name "$channel_name" || ! valid_id "$app_id" || ! valid_id "$guild_id" || ! valid_id "$channel_id"; then
    warn "非敏感的 App、服务器或频道资料尚未准备完整。请让代理在浏览器中核对填写；也可选择 --manual。"
    exit 1
  fi
  TOTAL_STAGES=1
  stage "输入 Discord Bot Token"
  say "$setup_slot · $app_name · $guild_name / $channel_name"
  say "应用和测试目的地已预填；你只需输入 Token。Enter 保留已有 Token，不重复填名称或 ID。"
  open_url "https://discord.com/developers/applications/$app_id/bot"
  warn "旧 Token 无法再次查看。只有确认可让旧 Token 失效并安排恢复后，才由你在页面中重置；向导不重置 Token。"
  bot_key="${prefix}_BOT_TOKEN"
  ask_secret "$bot_key" "Bot Token（隐藏输入）:"
  bot_value="${!bot_key}"
  [[ "$bot_value" =~ ^[A-Za-z0-9_.-]+$ && ${#bot_value} -ge 20 && ${#bot_value} -le 512 ]] || { warn "Bot Token 为空或格式无效。"; exit 1; }
  write_values "$bot_key=$bot_value" "BH_DISCORD_QA_SLOT=$setup_slot" "${prefix}_CONSOLE_READY=pending"
  say "Token 已保存，剩余身份、权限和配置由代理核对。此步骤不确认独占窗口，也不启动接收器。"
  finish
  exit 0
fi
if [[ -n "$setup_slot" ]]; then
  [[ "$setup_slot" =~ ^QA[123]$ ]] || { warn "请选择 QA1、QA2 或 QA3。"; exit 1; }
  IM_TEST_APP_VALUE_BH_DISCORD_QA_SLOT="$setup_slot"
fi

banner "BotHarness 共享 Discord QA App 配置"

stage "选择测试槽与独立 App"
say "Discord QA1/QA2/QA3 与 Lark、Slack 分别编号；每个槽对应一个独立测试 App。"
say "按 Enter 保留已保存的值。配置只留在本机，不启动接收器，也不写 GitHub secrets。"
open_url "https://discord.com/developers/applications"
step "选择已有测试应用；若没有，New Application 创建独立 QA App。在 General Information / 基本信息复制 Application ID。"
ask BH_DISCORD_QA_SLOT "Discord 测试槽 [QA1/QA2/QA3]:"
[[ "$BH_DISCORD_QA_SLOT" =~ ^QA[123]$ ]] || { warn "请选择 QA1、QA2 或 QA3。"; exit 1; }
prefix="BH_DISCORD_${BH_DISCORD_QA_SLOT}"
name_key="${prefix}_NAME"
id_key="${prefix}_APP_ID"
ask "$name_key" "App 名称:"
ask "$id_key" "Application ID（完整数字，不是名称或 Client Secret）:"
valid_name "${!name_key}" || { warn "App 名称不能为空或包含控制字符。"; exit 1; }
valid_id "${!id_key}" || { warn "Application ID 必须是有效的 Discord 数字 ID。"; exit 1; }
confirm "确认这是独立测试 App，且当前没有其他任务或设备接收它的事件？" || exit 1
write_values "BH_DISCORD_QA_SLOT=$BH_DISCORD_QA_SLOT" "$name_key=${!name_key}" "$id_key=${!id_key}" "${prefix}_RECEIVER_CHECKED_AT=$(date -u +%Y-%m-%dT%H:%M:%SZ)"

stage "隐藏输入 Bot Token"
open_url "https://discord.com/developers/applications/${!id_key}/bot"
step "Bot / 机器人 → Token / 令牌：使用这个 App 已保存的 Bot Token。按 Enter 可以保留本机已有 Token。"
warn "Discord 不会再次显示旧 Token。若未保存，只有在确认可让旧 Token 失效并安排恢复后，才由你点击 Reset Token / 重置令牌并完成验证。向导不会重置 Token。"
ask_secret "${prefix}_BOT_TOKEN" "Bot Token（隐藏输入；不要输入 Client Secret、Public Key 或 Bot 前缀）:"
bot_key="${prefix}_BOT_TOKEN"
bot_value="${!bot_key}"
[[ "$bot_value" =~ ^[A-Za-z0-9_.-]+$ && ${#bot_value} -ge 20 && ${#bot_value} -le 512 ]] || { warn "Bot Token 为空或格式无效。"; exit 1; }
write_values "$bot_key=${!bot_key}"
note "Token 只写入本机受保护的共享文件。不要 source、粘贴到聊天或加入 Git；后续加载器会私下传给 Provider。"

stage "确认测试服务器、频道与现有权限"
open_url "https://discord.com/channels/@me"
step "用户设置 → 高级 → 开发者模式：开启后，右键测试服务器和文字频道 → 复制服务器 ID / 复制频道 ID。数字 ID 按字符串保存。"
guild_name_key="${prefix}_GUILD_NAME"
guild_id_key="${prefix}_GUILD_ID"
channel_name_key="${prefix}_CHANNEL_NAME"
channel_id_key="${prefix}_CHANNEL_ID"
ask "$guild_name_key" "测试服务器名称:"
ask "$guild_id_key" "测试服务器 ID:"
ask "$channel_name_key" "测试文字频道名称:"
ask "$channel_id_key" "测试文字频道 ID（公开帖子的父频道）:"
valid_name "${!guild_name_key}" && valid_name "${!channel_name_key}" || { warn "服务器和频道名称不能为空或包含控制字符。"; exit 1; }
valid_id "${!guild_id_key}" && valid_id "${!channel_id_key}" || { warn "服务器和频道 ID 必须是有效的 Discord 数字 ID。"; exit 1; }
open_url "https://discord.com/channels/${!guild_id_key}/${!channel_id_key}"
step "核对该 App 已安装在上述测试服务器，且频道中允许它 View Channel / 查看频道、Read Message History / 读取消息历史、Send Messages / 发送消息。测试公开帖子还需 Send Messages in Threads / 在帖子中发送消息。"
step "若尚未安装：开发者页面 Installation / 安装 → Guild Install / 服务器安装，使用 bot scope 的安装链接，仅在指定测试服务器确认所需权限；不需要 Administrator。已有应用先核对，不自动改权限。"
say "本次 checked 契约接收服务器文字频道或现有公开帖子里的直接 @；不把 Discord 私聊视为已支持。"
say "直接 @ 不需要新增 Message Content 特权意图；普通消息收集、DM、配对和按钮审批属于各自验收。"
say "参考：https://docs.discord.com/developers/quick-start/getting-started"
say "参考：https://docs.discord.com/developers/events/gateway#message-content-intent"
if confirm "上述 App 安装、测试目的地和现有权限已核对完成？"; then
  ready=yes
else
  ready=pending
  SKIPPED+=("核对 Discord 测试服务器安装和频道权限")
fi
write_values "$guild_name_key=${!guild_name_key}" "$guild_id_key=${!guild_id_key}" "$channel_name_key=${!channel_name_key}" "$channel_id_key=${!channel_id_key}" "${prefix}_CONSOLE_READY=$ready"
say "完成后告知代理 Discord QA 槽即可，无需发送 Token。保存的名称、ID、检查时间不是身份认证或持续独占租约；每次接收器启动前仍须确认当前窗口。"
finish
